MATCH (p:Politician)-[:holdsPosition]->(pos:Position)
WHERE EXISTS {
  MATCH (p)-[:holdsPosition]->(:Position {name: "Rector provinciaes"})
}
WITH DISTINCT pos
RETURN count(pos)

MATCH (c:Country {name: "Rwanda"})-[:hasHeadOfState]->(p:Politician)
WHERE NOT EXISTS {
  MATCH (c)-[r:hasHeadOfState]->(p)
  WHERE r.end_year IS NOT NULL
}
RETURN DISTINCT p.name
